<?php
require '../db.php';require_role(['Admin']);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="mealdash-orders.csv"');$out=fopen('php://output','w');fputcsv($out,['Order ID','Customer','Restaurant','Status','Subtotal','Delivery fee','Total','Payment status','Address','Created']);$res=$conn->query('SELECT o.id,u.UserName,r.name,o.status,o.subtotal,o.delivery_fee,o.total,o.payment_status,o.delivery_address,o.created_at FROM orders o JOIN users u ON u.UserID=o.customer_id JOIN restaurants r ON r.id=o.restaurant_id ORDER BY o.created_at DESC');while($row=$res->fetch_row())fputcsv($out,$row);fclose($out);
